import {renderSubjectTrend} from './grade-trends.mjs';
import {roster,studentById,classes as allClasses,today,csv} from './model.mjs';
const average=values=>values.length?values.reduce((a,b)=>a+b,0)/values.length:null;
const pct=v=>v===null||v===undefined?'—':Math.round(v*10)/10+'%';
const delta=v=>v===null?'—':(v>0?'+':'')+(Math.round(v*10)/10)+' pp';
export function createGradesUI(ui){
 const {esc,button,person,empty,options}=ui,$=s=>document.querySelector(s),books=new Map(),profiles=new Map(),assessmentViews=new Map();let editor=null,mode='entry',saving=false,pending=null,trendSubject='',trendStudentId=null;
 async function api(path,options={}){const response=await fetch('/api/grades'+path,{credentials:'same-origin',cache:'no-store',...options,headers:{'Content-Type':'application/json',...options.headers}});const data=await response.json();if(!response.ok)throw Error(data.error||'Could not load grades.');return data;}
 async function migrate(root,teacher){const own=new Set(ui.classes().map(c=>c.id));await api('/import',{method:'POST',body:JSON.stringify({assignments:root.assignments.filter(a=>own.has(a.classId)),grades:root.grades})});}
 function loadBook(classId){books.set(classId,{loading:true});api('/class?'+new URLSearchParams({classId})).then(data=>books.set(classId,data)).catch(error=>books.set(classId,{error:error.message})).finally(()=>{if(ui.route().path==='/classes'&&ui.route().params.get('tab')==='gradebook'&&ui.route().params.get('class')===classId&&!editor?.dirty)ui.render();});}
 function openEditor(c,a){editor={classId:c.id,id:a?.id||null,expectedRevision:a?.revision||0,title:a?.title||'',date:a?.date||today(),maximum:a?.maximum??'',missedStudentIds:a?.missedStudentIds||[],marks:Object.fromEntries(roster(c.id).map(s=>[s.id,a?.marks[s.id]??''])),dirty:false};}
 function requestChange(fn){if(!editor?.dirty){fn();return;}pending=fn;ui.openDialog('Keep your assessment changes?','<p>This assessment has unsaved marks or details.</p>',button('Keep editing','close')+button('Discard changes','grades-discard','','danger'));}
 function page(c){const book=books.get(c.id);if(!book){loadBook(c.id);return '<section class="panel"><div class="empty">Loading shared gradebook…</div></section>';}if(book.error)return '<div id="page-error" class="error">'+esc(book.error)+'</div>'+button('Retry','grades-retry',`data-id="${c.id}"`);if(book.loading)return '<section class="panel"><div class="empty">Loading shared gradebook…</div></section>';
  if(!editor||editor.classId!==c.id){const selected=ui.route().params.get('assignment');openEditor(c,book.assessments.find(a=>a.id===selected||a.sourceId===selected)||book.assessments.at(-1));}if(editor.dirty)ui.setDirty(true);
  const controls=`<div class="grade-toolbar"><div class="grade-mode" role="group" aria-label="Gradebook view">${button('Mark entry','grades-mode','data-mode="entry"',mode==='entry'?'primary small':'small')}${button('Class tracking sheet','grades-mode','data-mode="class"',mode==='class'?'primary small':'small')}${button('All my students','grades-mode','data-mode="all"',mode==='all'?'primary small':'small')}</div>${button('+ New assessment','grades-new',`data-id="${c.id}"`,'primary small')}</div><div id="page-error" class="error" role="alert"></div>`;
  if(mode==='all')return controls+allTracking(c);
  if(mode==='class')return controls+trackingSheet(c,book.assessments);
  return controls+`<div class="assessment-meta"><label class="field"><span>Saved assessment</span><select id="assessment-select">${options([['','New assessment'],...book.assessments.map(a=>[a.id,a.title+' · '+a.date])],editor.id||'')}</select></label><label class="field assessment-name"><span>Assessment name</span><input id="assessment-title" maxlength="160" value="${esc(editor.title)}" placeholder="e.g. Algorithms quiz"></label><label class="field"><span>Out of / maximum mark</span><input id="assessment-maximum" type="number" min="0.01" max="10000" step="any" value="${editor.maximum}" placeholder="e.g. 20"></label><label class="field"><span>Assessment date</span><input id="assessment-date" type="date" value="${editor.date}"></label></div><section class="panel grades-panel"><div class="panel-head"><div><h2>Enter student marks</h2><p>Blank = ungraded · Missed = not taken · 0 = zero marks</p></div><span id="assessment-count" class="badge">${Object.values(editor.marks).filter(v=>v!=='').length} / ${roster(c.id).length} marked</span></div><div class="table-wrap"><table class="data-table assessment-table"><thead><tr><th>Student</th><th>Mark</th><th>Percentage</th></tr></thead><tbody>${roster(c.id).map(s=>`<tr><td><button class="student-link" data-action="student" data-id="${s.id}">${person(s)}</button></td><td><input class="score-input" type="number" min="0" ${Number(editor.maximum)>0?`max="${editor.maximum}"`:''} step="any" data-assessment-score="${s.id}" aria-label="Mark for ${esc(s.name)}" value="${editor.marks[s.id]}"></td><td id="assessment-pct-${s.id}" class="grade-percentage">${editor.marks[s.id]===''&&editor.missedStudentIds?.includes(s.id)?'<span class="missed-assessment">Missed</span>':editor.marks[s.id]===''||!Number(editor.maximum)?'—':pct(Number(editor.marks[s.id])/Number(editor.maximum)*100)}</td></tr>`).join('')}</tbody></table></div></section><div class="save-bar"><span id="save-status">${editor.dirty?'Unsaved assessment changes':editor.id?'Saved to shared student tracking':'New assessment · enter the maximum mark, then student marks'}</span><div class="actions">${button('Cancel changes','grades-cancel')}${button('Save assessment','grades-save','','primary')}</div></div>`;
 }
 function trackingSheet(c,assessments){return `<section class="panel grades-panel"><div class="panel-head"><div><h2>Class tracking sheet</h2><p>${roster(c.id).length} students · ${assessments.length} saved assessments · percentages</p></div>${button('Export tracking CSV','grades-export',`data-id="${c.id}"`,'small')}</div><div class="table-wrap"><table class="data-table tracking-table"><thead><tr><th>Student</th>${assessments.map(a=>`<th title="${esc(a.title)} · ${a.date} · out of ${a.maximum}">${esc(a.title)}<small>${a.date} · /${a.maximum}</small></th>`).join('')}<th>Overall mean</th></tr></thead><tbody>${roster(c.id).map(s=>{const marks=assessments.map(a=>a.marks[s.id]===undefined?null:a.marks[s.id]/a.maximum*100);return `<tr><th><button class="student-link" data-action="student" data-id="${s.id}">${esc(s.name)}</button></th>${marks.map((v,i)=>`<td>${assessments[i].missedStudentIds?.includes(s.id)?'<span class="missed-assessment">Missed</span>':pct(v)}</td>`).join('')}<td><strong>${pct(average(marks.filter(v=>v!==null)))}</strong></td></tr>`;}).join('')}<tr class="class-average-row"><th>Class average</th>${assessments.map(a=>`<td>${pct(a.classAverage)}</td>`).join('')}<td>${pct(average(assessments.filter(a=>a.classAverage!==null).map(a=>a.classAverage)))}</td></tr></tbody></table></div></section><p class="grade-method">Overall mean = equal average of marked assessment percentages. Missed and ungraded entries are excluded.</p>`;}
 let schoolTracking=null;
 function allTracking(){if(!schoolTracking){schoolTracking={loading:true};api('/tracking').then(data=>schoolTracking=data).catch(error=>schoolTracking={error:error.message}).finally(()=>{if(ui.route().params.get('tab')==='gradebook'&&mode==='all')ui.render();});return empty('Loading student tracking','');}if(schoolTracking.loading)return empty('Loading student tracking','');if(schoolTracking.error)return '<div class="error">'+esc(schoolTracking.error)+'</div>';
 const subjects=[...new Set(schoolTracking.entries.map(e=>e.subject))].sort();return `<section class="panel grades-panel"><div class="panel-head"><div><h2>All my students · all subjects</h2><p>Every allocated student, with results saved by all their teachers.</p></div>${button('Export tracking CSV','grades-export-all','','small')}</div><div class="table-wrap"><table class="data-table tracking-table"><thead><tr><th>Student</th>${subjects.map(s=>'<th>'+esc(s)+'</th>').join('')}<th>Overall mean</th></tr></thead><tbody>${ui.students().map(s=>{const entries=schoolTracking.entries.filter(e=>e.studentId===s.id&&e.percentage!==null);return '<tr><th>'+button(esc(s.name),'student',`data-id="${s.id}"`,'small')+'</th>'+subjects.map(subject=>'<td>'+pct(average(entries.filter(e=>e.subject===subject).map(e=>e.percentage)))+'</td>').join('')+'<td>'+pct(average(entries.map(e=>e.percentage)))+'</td></tr>';}).join('')}</tbody></table></div></section><p class="grade-method">Subject and overall means give each marked assessment equal weight. Blank cells mean no saved marks.</p>`;}
 async function save(){if(saving||!editor)return;const e=editor,maximum=Number(e.maximum);if(!e.title.trim()||!Number.isFinite(maximum)||maximum<=0||maximum>10000||!/^\d{4}-\d{2}-\d{2}$/.test(e.date)){ui.error('Enter an assessment name, valid date and a maximum mark greater than zero.');return;}const marks={};for(const[id,value]of Object.entries(e.marks)){if(value==='')continue;const mark=Number(value);if(!Number.isFinite(mark)||mark<0||mark>maximum){ui.error('Every mark must be between 0 and '+maximum+'. Leave an ungraded mark blank.');return;}marks[id]=mark;}
 saving=true;const controls=[...document.querySelectorAll('#main input,#main select,#main button')];controls.forEach(el=>el.disabled=true);try{const {assessment}=await api('/assessment',{method:'PUT',body:JSON.stringify({...e,maximum,marks})});editor={...assessment,expectedRevision:assessment.revision,dirty:false,marks:Object.fromEntries(roster(e.classId).map(s=>[s.id,assessment.marks[s.id]??'']))};books.delete(e.classId);profiles.clear();assessmentViews.clear();schoolTracking=null;ui.setDirty(false);ui.render();ui.toast('Assessment saved to shared student tracking.');}catch(error){ui.error(error.message);}finally{saving=false;controls.forEach(el=>{if(el.isConnected)el.disabled=false;});}}
 function input(t){if(!editor)return;if(t.dataset.assessmentScore){editor.marks[t.dataset.assessmentScore]=t.value;const v=t.value===''||!Number(editor.maximum)?null:Number(t.value)/Number(editor.maximum)*100;$('#assessment-pct-'+t.dataset.assessmentScore).textContent=v===null&&editor.missedStudentIds?.includes(t.dataset.assessmentScore)?'Missed':pct(v);t.setAttribute('aria-invalid',String(v!==null&&(v<0||v>100)));$('#assessment-count').textContent=Object.values(editor.marks).filter(v=>v!=='').length+' / '+roster(editor.classId).length+' marked';}
 else if(['assessment-title','assessment-maximum','assessment-date'].includes(t.id)){editor[{'assessment-title':'title','assessment-maximum':'maximum','assessment-date':'date'}[t.id]]=t.value;if(t.id==='assessment-maximum')document.querySelectorAll('[data-assessment-score]').forEach(el=>{el.max=t.value;$('#assessment-pct-'+el.dataset.assessmentScore).textContent=el.value===''&&editor.missedStudentIds?.includes(el.dataset.assessmentScore)?'Missed':el.value===''||!Number(t.value)?'—':pct(Number(el.value)/Number(t.value)*100);});}else return;editor.dirty=true;ui.setDirty(true);}
 async function exportTracking(classId){try{let entries;if(classId){const book=await api('/class?'+new URLSearchParams({classId}));entries=book.assessments.flatMap(a=>roster(classId).map(s=>({studentId:s.id,studentNumber:s.studentNumber,title:a.title,date:a.date,subject:allClasses.find(c=>c.id===classId).subject,className:allClasses.find(c=>c.id===classId).name,maximum:a.maximum,mark:a.marks[s.id]??null,percentage:a.marks[s.id]===undefined?null:a.marks[s.id]/a.maximum*100,missed:a.missedStudentIds?.includes(s.id)||false,classAverage:a.classAverage})));}else entries=(await api('/tracking')).entries;ui.download('student-grade-tracking.csv',csv([['Student ID','Student','Subject','Teaching group','Assessment','Date','Mark','Out of','Percentage','Class average','Status'],...entries.map(e=>[e.studentNumber,studentById(e.studentId).name,e.subject,e.className,e.title,e.date,e.mark??'',e.maximum,e.percentage??'',e.classAverage??'',e.missed?'Missed':e.mark===null?'Ungraded':'Marked'])]));}catch(error){ui.error(error.message);}}
 function handleAction(action,a){const id=a.dataset.id;if(action==='grades-trend-subject'){trendSubject=a.dataset.subject||'';drawDashboard();return true;}if(action==='grades-refresh-assessment'){assessmentViews.delete(id);ui.render();return true;}if(action==='grades-open-editor'){const view=assessmentViews.get(id);if(view?.canEdit){editor=null;mode='entry';books.delete(view.assessment.classId);ui.navigate('/classes',{class:view.assessment.classId,tab:'gradebook',assignment:id});}return true;}if(action==='grades-refresh'){requestChange(()=>{profiles.clear();books.clear();schoolTracking=null;editor=null;ui.setDirty(false);ui.render();});return true;}if(action==='grades-new'){requestChange(()=>{mode='entry';openEditor(allClasses.find(c=>c.id===id));editor.dirty=true;ui.render();});return true;}if(action==='grades-mode'){requestChange(()=>{editor.dirty=false;mode=a.dataset.mode;ui.setDirty(false);ui.render();});return true;}if(action==='grades-save'){void save();return true;}if(action==='grades-discard'){ui.closeDialog(true);editor.dirty=false;ui.setDirty(false);const fn=pending;pending=null;fn?.();return true;}if(action==='grades-cancel'){requestChange(()=>{openEditor(allClasses.find(c=>c.id===editor.classId),books.get(editor.classId)?.assessments.find(a=>a.id===editor.id));ui.setDirty(false);ui.render();});return true;}if(action==='grades-retry'){books.delete(id);ui.render();return true;}if(action==='grades-export'||action==='grades-export-all'){void exportTracking(action==='grades-export'?id:null);return true;}return false;}
 function change(t){if(t.id==='assessment-select'){const selected=t.value;requestChange(()=>{openEditor(allClasses.find(c=>c.id===editor.classId),books.get(editor.classId).assessments.find(a=>a.id===selected));ui.setDirty(false);ui.render();});t.value=editor.id||'';return;}if(['student-grade-subject','student-grade-from','student-grade-to'].includes(t.id)){trendSubject='';drawDashboard();}}
 async function loadProfile(s){profiles.set(s.id,{loading:true});try{const c=ui.classes().find(c=>c.studentIds.includes(s.id));const [grades,attendance]=await Promise.all([api('/tracking?'+new URLSearchParams({studentId:s.id})),ui.attendanceApi('/report?'+new URLSearchParams({classId:c.id,from:'2026-08-01',to:today(),scope:'students'}))]);profiles.set(s.id,{...grades,attendance:attendance.entries.filter(e=>e.studentId===s.id)});}catch(error){profiles.set(s.id,{error:error.message});}if(ui.route().path==='/student'&&ui.route().params.get('id')===s.id)ui.render();}
 function studentPage(params){const s=ui.students().find(s=>s.id===params.get('id'));if(!s)return empty('Student unavailable','Choose a student allocated to your account.');if(trendStudentId!==s.id){trendStudentId=s.id;trendSubject='';}let data=profiles.get(s.id);if(!data){void loadProfile(s);data={loading:true};}const grades=params.get('tab')==='grades';const header=`<div class="student-profile-head compact-student-head"><div class="student-heading-line"><h1 class="student-name-heading">${person(s)}</h1><span class="student-heading-meta">${esc(s.groupName)} · ${grades?'Grades':esc(s.status)}</span></div><div class="actions"><a class="btn small" href="#/directory?type=student">Directory</a><a class="btn small" href="#/person?id=${s.id}">Bio & contacts</a><a class="btn ${grades?'':'primary'} small" href="#/student?id=${s.id}">Daily overview</a><a class="btn ${grades?'primary':''} small" href="#/student?id=${s.id}&tab=grades">Grades</a>${grades?button('↻','grades-refresh','aria-label="Refresh student grades" title="Refresh student grades"','small'):''}</div></div>`;
 if(data.loading)return header+empty('Loading student records','');if(data.error)return header+'<div class="error">'+esc(data.error)+'</div>';
 if(grades)return header+`<div class="analytics-filters"><label class="field"><span>Subject</span><select id="student-grade-subject">${options([['','All subjects'],...data.subjects.map(s=>[s,s])],'')}</select></label><label class="field"><span>From</span><input type="date" id="student-grade-from" value="2026-08-01"></label><label class="field"><span>To</span><input type="date" id="student-grade-to" value="${today()}"></label></div><div id="student-grade-dashboard">${dashboard(s,data,'','2026-08-01',today())}</div>`;
 const incidents=ui.state().incidents.filter(i=>i.studentId===s.id),attendance=data.attendance,recorded=attendance.filter(e=>e.status!=='Not Taken'),present=recorded.filter(e=>['Present','Internal Inclusion'].includes(e.status)||e.status.startsWith('Late')).length;return header+`<div class="student-daily-grid"><section class="panel"><div class="panel-head"><h2>Daily information</h2></div><div class="panel-body"><dl class="student-info"><dt>Form</dt><dd>${esc(s.groupName)}</dd><dt>Date of birth</dt><dd>${esc(s.dateOfBirth)}</dd><dt>School email</dt><dd>${esc(s.schoolEmail)}</dd><dt>Teaching groups</dt><dd>${ui.classes().filter(c=>c.studentIds.includes(s.id)).map(c=>esc(c.name)).join('<br>')}</dd></dl><p class="muted">Fictional test profile. Bio & contacts contains linked household, emergency and medical test records.</p></div></section><section class="panel"><div class="panel-head"><h2>Attendance</h2><span class="badge">${recorded.length?pct(present/recorded.length*100):'No saved marks'}</span></div><div class="panel-body"><p class="muted">Lesson attendance since 1 August · present includes late arrivals.</p>${attendance.length?`<div class="student-history">${attendance.slice().reverse().slice(0,12).map(e=>`<div><strong>${esc(e.date)} · Period ${esc(e.period)}</strong><span>${esc(e.status)} ${esc(e.time||'')}</span><small>${esc(allClasses.find(c=>c.id===e.classId).name)}${e.note?' · '+esc(e.note):''}</small></div>`).join('')}</div>`:empty('No saved attendance','Registers will appear here after teachers save them.')}</div></section><section class="panel"><div class="panel-head"><h2>Behaviour and follow-up</h2><span class="badge">${incidents.length}</span></div><div class="panel-body">${incidents.map(i=>`<div class="student-history"><strong>${esc(i.title)}</strong><p>${esc(i.date)} · ${esc(i.severity)}</p><p>${esc(i.description)}</p><p>${esc(i.followup||'No follow-up recorded.')}</p></div>`).join('')||'<p class="muted">No incidents recorded by you in this browser.</p>'}</div></section></div>`;}
 function dashboard(s,data,subject,from,to){if(from&&to&&from>to)return '<div class="error">The From date must be before the To date.</div>';const entries=data.entries.filter(e=>(!subject||e.subject===subject)&&(!from||e.date>=from)&&(!to||e.date<=to)),marked=entries.filter(e=>e.percentage!==null),studentMean=average(marked.map(e=>e.percentage)),peerMean=average(marked.filter(e=>e.classAverage!==null).map(e=>e.classAverage)),subjects=(subject?[subject]:data.subjects).slice().sort((a,b)=>Number(marked.some(e=>e.subject===b))-Number(marked.some(e=>e.subject===a))||a.localeCompare(b));
 const summary=`<div class="analytics-kpis">${[['Student average',pct(studentMean),'Mean of marked assessment percentages'],['Class comparison',delta(studentMean===null||peerMean===null?null:studentMean-peerMean),'Against class means for the same assessments'],['Marked assessments',String(marked.length),entries.filter(e=>e.missed).length+' missed · '+entries.length+' saved assessments'],['Subjects with marks',String(new Set(marked.map(e=>e.subject)).size),subjects.length+' subjects in this view']].map(([label,value,note])=>`<div class="analytics-kpi"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`).join('')}</div>`;
 const bars=`<section class="panel"><div class="panel-head"><h2>By subject</h2><div class="chart-legend"><span class="student-key">Student</span><span class="class-key">Class average</span></div></div><div class="subject-comparison">${subjects.map(subject=>{const subjectEntries=entries.filter(e=>e.subject===subject),latest=subjectEntries.at(-1),rows=marked.filter(e=>e.subject===subject),own=average(rows.map(e=>e.percentage)),peer=average(rows.map(e=>e.classAverage).filter(v=>v!==null));return `<div class="subject-comparison-row"><div><strong>${latest?`<a class="assessment-link" href="#/assessment?id=${encodeURIComponent(latest.assessmentId)}&student=${s.id}" title="Open latest assessment: ${esc(latest.title)}">${esc(subject)} ↗</a>`:esc(subject)}</strong><small>${rows.length} marked assessment${rows.length===1?'':'s'}</small></div><div class="comparison-bars"><label><span class="sr-only">Student average for ${esc(subject)}</span><progress max="100" value="${own??0}" class="student-progress"></progress><b>${pct(own)}</b></label><label><span class="sr-only">Class average for ${esc(subject)}</span><progress max="100" value="${peer??0}" class="class-progress"></progress><b>${pct(peer)}</b></label></div><span class="comparison-delta">${delta(own===null||peer===null?null:own-peer)}</span></div>`;}).join('')}</div></section>`;
 const trend=renderSubjectTrend(entries,{subjects:data.subjects,selectedSubject:trendSubject,esc,pct});
 const details=`<section class="panel analytics-results"><div class="panel-head"><h2>Assessment detail</h2><span class="badge">${entries.length} assessments</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Date / subject</th><th>Assessment</th><th>Mark</th><th>Student</th><th>Class average</th><th>Difference</th></tr></thead><tbody>${entries.slice().reverse().map(e=>`<tr><td>${esc(e.date)}<small><a class="assessment-link" href="#/assessment?id=${encodeURIComponent(e.assessmentId)}&student=${s.id}">${esc(e.subject)} ↗</a></small></td><td><strong><a class="assessment-link" href="#/assessment?id=${encodeURIComponent(e.assessmentId)}&student=${s.id}">${esc(e.title)}</a></strong><small>${esc(e.className)} · ${esc(e.teacher)}</small></td><td>${e.missed?'<span class="missed-assessment">Missed</span>':e.mark===null?'Ungraded':e.mark+' / '+e.maximum}</td><td>${pct(e.percentage)}</td><td>${pct(e.classAverage)}<small>${e.classCount} marked students</small></td><td>${delta(e.percentage===null||e.classAverage===null?null:e.percentage-e.classAverage)}</td></tr>`).join('')}</tbody></table></div></section>`;
 return summary+`<div class="analytics-charts">${bars}${trend}</div>`+details+'<p class="grade-method">All figures use saved marks. Averages give each marked assessment equal weight; missed and ungraded entries are excluded and zero is included. Comparisons use the same assessments and each assessment’s own teaching group. “pp” = percentage points. No assessment saved for a subject means no grade is shown.</p>';}
 function assessmentPage(params){const id=params.get('id'),student=params.get('student'),view=assessmentViews.get(id);if(!view){assessmentViews.set(id,{loading:true});api('/assessment?'+new URLSearchParams({id:id||''})).then(data=>assessmentViews.set(id,data)).catch(error=>assessmentViews.set(id,{error:error.message})).finally(()=>{if(ui.route().path==='/assessment'&&ui.route().params.get('id')===id)ui.render();});return empty('Loading saved assessment','');}const back=student&&ui.students().some(s=>s.id===student)?'#/student?id='+student+'&tab=grades':'#/directory';if(view.loading)return empty('Loading saved assessment','');if(view.error)return '<div class="error">'+esc(view.error)+'</div><a class="btn" href="'+back+'">Back</a>';const a=view.assessment;return `<div class="assessment-review-head"><div><span class="eyebrow">SAVED ASSESSMENT</span><h1>${esc(a.title)}</h1><p>${esc(view.subject)} · ${esc(view.className)} · ${esc(view.teacher)} · ${esc(a.date)} · Out of ${a.maximum}</p></div><div class="actions">${button('Refresh','grades-refresh-assessment',`data-id="${esc(a.id)}"`,'small')}<a class="btn small" href="${back}">Back to student grades</a>${view.canEdit?button('Open gradebook','grades-open-editor',`data-id="${esc(a.id)}"`,'primary small'):''}</div></div><section class="panel"><div class="panel-head"><div><h2>Saved student grades</h2><p>${view.studentIds.length===view.classSize?'All '+view.classSize+' students':'Showing '+view.studentIds.length+' allocated students from a class of '+view.classSize} · ${view.markedCount} marked in the full class · Revision ${a.revision}</p></div><span class="badge">Class average ${pct(a.classAverage)}</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>Mark / ${a.maximum}</th><th>Percentage</th><th>Class average</th><th>Difference</th></tr></thead><tbody>${view.studentIds.map(id=>{const pupil=studentById(id),mark=a.marks[id],percentage=mark===undefined?null:mark/a.maximum*100;return `<tr><td>${person(pupil)}</td><td>${a.missedStudentIds?.includes(id)?'<span class="missed-assessment">Missed</span>':mark===undefined?'Ungraded':mark+' / '+a.maximum}</td><td>${pct(percentage)}</td><td>${pct(a.classAverage)}</td><td>${delta(percentage===null||a.classAverage===null?null:percentage-a.classAverage)}</td></tr>`;}).join('')}</tbody></table></div></section><p class="grade-method">Read-only saved assessment. The class average includes entered marks only; blank marks remain ungraded.</p>`;}
 function drawDashboard(){const id=ui.route().params.get('id'),data=profiles.get(id);if(!data||data.loading||data.error)return;$('#student-grade-dashboard').innerHTML=dashboard(studentById(id),data,$('#student-grade-subject').value,$('#student-grade-from').value,$('#student-grade-to').value);}
 return{page,studentPage,assessmentPage,input,change,handleAction,migrate,api,invalidate(){books.clear();profiles.clear();assessmentViews.clear();schoolTracking=null;editor=null;}};
}
